from pyspark import pipelines as dp
from pyspark.sql.functions import *

# Environment parameterization
env = spark.conf.get('__BLANK_0__', 'dev')

# CDC: Track order status changes
dp.__BLANK_1__(
    target='silver_orders',
    source='bronze_order_events',
    keys=['order_id'],
    __BLANK_2__='updated_at',
    apply_as_deletes=expr("operation = 'DELETE'"),
    apply_as_truncates=expr("operation = 'TRUNCATE'")
)

# Gold: Order summary with freshness tracking
@dp.table(
    comment='Aggregated order metrics with SLA tracking'
)
def gold_order_metrics():
    return (
        dp.__BLANK_3__('silver_orders')
        .groupBy('order_status', window('updated_at', '1 hour'))
        .agg(
            count('*').alias('order_count'),
            sum('total_amount').alias('revenue'),
            __BLANK_4__('updated_at').alias('latest_update')
        )
    )

# Dead letter queue for failed records
@dp.table
def __BLANK_5__():
    return (
        dp.read_stream('bronze_order_events')
        .filter('order_id IS NULL OR total_amount < 0')
        .withColumn('failure_reason',
            when(col('order_id').isNull(), 'missing_order_id')
            .otherwise('negative_amount')
        )
    )
